/* English build of map.js — generated by cli/i18n.php, do not edit */
/* ==========================================================================
   Network map: Sites, MikroTik devices, Subscribers, Links
   ========================================================================== */
(function (window, document) {
  'use strict';

  var cfgNode = document.getElementById('map-config');
  var holder = document.getElementById('net-map');
  if (!cfgNode || !holder || !window.L || !window.SNGeo) { return; }

  var L = window.L;
  var SN = window.SN;
  var cfg = JSON.parse(cfgNode.textContent);
  var esc = SN.esc;

  var map = L.map(holder, { zoomControl: true, worldCopyJump: true });
  map.setView([cfg.view[0], cfg.view[1]], cfg.view[2]);
  SNGeo.attachLayers(map);

  var groups = {
    links: L.layerGroup().addTo(map),
    subscribers: L.layerGroup().addTo(map),
    sites: L.layerGroup().addTo(map),
    routers: L.layerGroup().addTo(map)
  };
  var markers = { sites: {}, routers: {}, subscribers: {}, links: {} };
  var data = { sites: [], routers: [], subscribers: [], links: [] };
  var mode = '';            // '' | add | move | link
  var linkFrom = null;
  var firstLoad = true;

  var ROUTER_STATUS = { online: ['Connected', 'badge-success', 'is-online'], offline: ['Offline', 'badge-danger', 'is-offline'], unknown: ['Unknown', 'badge-outline', 'is-unknown'] };
  var SUB_STATE = {
    active: ['Active', 'badge-success', 'is-active'], expiring: ['Expiring soon', 'badge-warning', 'is-expiring'],
    expired: ['Expired', 'badge-danger', 'is-expired'], suspended: ['Suspended', 'badge-danger', 'is-expired'], 'new': ['Awaiting activation', 'badge-info', 'is-new']
  };
  var LINK_STYLE = {
    fiber: { color: '#f97316', weight: 4, opacity: 0.9 },
    wireless: { color: '#2563eb', weight: 3, opacity: 0.9, dashArray: '8 7' },
    cable: { color: '#64748b', weight: 3, opacity: 0.9 },
    other: { color: '#a855f7', weight: 2, opacity: 0.9, dashArray: '2 7' }
  };

  function url(path) { return cfg.base + path; }

  // ------------------------------------------------------------------------
  // النوافذ المنبثقة
  // ------------------------------------------------------------------------
  function sitePopup(s) {
    var t = cfg.siteTypes[s.type] || { label: s.type };
    var rows = '<div class="pop-sub">' + esc(t.label) + (s.area ? ' · ' + esc(s.area) : '') + (s.height ? ' · ' + s.height + ' m' : '') + '</div>' +
      '<div class="pop-stats"><span>' + SN.icon('router') + SN.fmtNum(s.routers) + '</span>' +
      (cfg.canSubs ? '<span>' + SN.icon('users') + SN.fmtNum(s.subscribers) + '</span>' : '') +
      '<span>' + SN.icon('hard-drive') + SN.fmtNum(s.units) + '</span></div>' +
      (s.address ? '<div class="pop-sub">' + esc(s.address) + '</div>' : '');
    var actions = '<a class="btn btn-xs" href="' + url('/sites/' + s.id) + '">' + SN.icon('info') + 'Details</a>';
    if (cfg.canManage) {
      actions += '<button type="button" class="btn btn-xs" data-pop="edit-site" data-id="' + s.id + '">' + SN.icon('pencil') + 'Edit</button>' +
        '<button type="button" class="btn btn-xs" data-pop="link-from" data-id="' + s.id + '">' + SN.icon('waypoints') + 'Link</button>';
    }
    return '<div class="pop"><div class="pop-title">' + esc(s.name) + '</div>' + rows + '<div class="pop-actions">' + actions + '</div></div>';
  }

  function routerPopup(r) {
    var st = ROUTER_STATUS[r.status] || ROUTER_STATUS.unknown;
    return '<div class="pop"><div class="pop-title">' + esc(r.name) + '</div>' +
      '<div class="pop-sub"><span class="badge ' + st[1] + '">' + st[0] + '</span>' + (r.site ? ' · ' + esc(r.site) : '') + '</div>' +
      '<div class="pop-stats"><span>' + SN.icon('users') + SN.fmtNum(r.clients) + ' Connected</span>' + (r.cpu !== null ? '<span>' + SN.icon('cpu') + r.cpu + '%</span>' : '') + '</div>' +
      '<div class="pop-actions"><a class="btn btn-xs" href="' + url('/routers/' + r.id) + '">' + SN.icon('router') + 'Open MikroTik device</a>' +
      (cfg.canManage ? '<button type="button" class="btn btn-xs" data-pop="edit-router" data-id="' + r.id + '">' + SN.icon('pencil') + 'Name and location</button>' : '') +
      (cfg.canManage && r.own ? '<button type="button" class="btn btn-xs text-danger" data-pop="unplace-router" data-id="' + r.id + '">' + SN.icon('trash-2') + 'Remove from map</button>' : '') +
      '</div></div>';
  }

  function subPopup(s) {
    var st = SUB_STATE[s.state] || SUB_STATE.active;
    return '<div class="pop"><div class="pop-title">' + esc(s.name) + '</div>' +
      '<div class="pop-sub"><span class="badge ' + st[1] + '">' + st[0] + '</span>' + (s.online ? ' <span class="badge badge-success badge-dot">Online now</span>' : '') + '</div>' +
      '<div class="pop-sub">' + esc(s.plan) + (s.site ? ' · ' + esc(s.site) : '') + '</div>' +
      '<div class="pop-actions"><a class="btn btn-xs" href="' + url('/subscribers/' + s.id) + '">' + SN.icon('user') + 'Open subscriber</a></div></div>';
  }

  // ------------------------------------------------------------------------
  // الرسم (Refresh in مكانه دون Close النوافذ Open)
  // ------------------------------------------------------------------------
  function sync(kind, list, build, update) {
    var seen = {};
    list.forEach(function (item) {
      seen[item.id] = true;
      var m = markers[kind][item.id];
      if (m) { update(m, item); } else { markers[kind][item.id] = build(item).addTo(groups[kind]); }
    });
    Object.keys(markers[kind]).forEach(function (id) {
      if (!seen[id]) { groups[kind].removeLayer(markers[kind][id]); delete markers[kind][id]; }
    });
  }

  function siteIcon(s) { return SNGeo.icon((cfg.siteTypes[s.type] || {}).icon || 'map-pin', 'mk-site', 34); }
  function routerIcon(r) { return SNGeo.icon('router', 'mk-router ' + (ROUTER_STATUS[r.status] || ROUTER_STATUS.unknown)[2], 28); }
  function subIcon(s) { return SNGeo.dot((SUB_STATE[s.state] || SUB_STATE.active)[2] + (s.online ? ' is-online' : '')); }

  function bindDrag(m, type, id) {
    m.on('dragend', function () {
      var p = m.getLatLng();
      SN.api(cfg.positionUrl, { method: 'POST', data: { type: type, id: id, lat: p.lat, lng: p.lng } })
        .then(function () { SN.toast('success', 'Location saved.'); load(); })
        .catch(function () { load(); });
    });
  }

  function render() {
    sync('links', data.links, function (l) {
      return L.polyline([[l.a.lat, l.a.lng], [l.b.lat, l.b.lng]], LINK_STYLE[l.type] || LINK_STYLE.other)
        .bindTooltip(esc((cfg.linkTypes[l.type] || l.type) + (l.capacity ? ' · ' + l.capacity : '') + (l.label ? ' · ' + l.label : '')), { sticky: true, direction: 'top' })
        .bindPopup(linkPopup(l));
    }, function (m, l) {
      m.setLatLngs([[l.a.lat, l.a.lng], [l.b.lat, l.b.lng]]);
      m.setStyle(LINK_STYLE[l.type] || LINK_STYLE.other);
      m.setPopupContent(linkPopup(l));
    });
    sync('subscribers', data.subscribers, function (s) {
      var m = L.marker([s.lat, s.lng], { icon: subIcon(s), draggable: mode === 'move' }).bindPopup(subPopup(s));
      bindDrag(m, 'subscriber', s.id);
      return m;
    }, function (m, s) { m.setLatLng([s.lat, s.lng]); m.setIcon(subIcon(s)); m.setPopupContent(subPopup(s)); });
    sync('sites', data.sites, function (s) {
      var m = L.marker([s.lat, s.lng], { icon: siteIcon(s), draggable: mode === 'move', zIndexOffset: 200 }).bindPopup(sitePopup(s));
      m.on('click', function () { if (mode === 'link') { pickLinkEnd(s); } });
      bindDrag(m, 'site', s.id);
      label(m, s.name, 'is-site', 20);
      return m;
    }, function (m, s) { m.setLatLng([s.lat, s.lng]); m.setIcon(siteIcon(s)); m.setPopupContent(sitePopup(s)); label(m, s.name, 'is-site', 20); });
    sync('routers', data.routers, function (r) {
      var m = L.marker([r.lat, r.lng], { icon: routerIcon(r), draggable: mode === 'move', zIndexOffset: 400 }).bindPopup(routerPopup(r));
      bindDrag(m, 'router', r.id);
      label(m, r.name, 'is-router ' + (ROUTER_STATUS[r.status] || ROUTER_STATUS.unknown)[2], 17);
      return m;
    }, function (m, r) { m.setLatLng([r.lat, r.lng]); m.setIcon(routerIcon(r)); m.setPopupContent(routerPopup(r)); label(m, r.name, 'is-router ' + (ROUTER_STATUS[r.status] || ROUTER_STATUS.unknown)[2], 17); });

    ['sites', 'routers', 'subscribers', 'links'].forEach(function (k) {
      var el = document.querySelector('[data-count="' + k + '"]');
      if (el) { el.textContent = SN.fmtNum(data[k].length); }
    });
    declutterSoon();
  }

  // ------------------------------------------------------------------------
  // Device and site names on the map: ظاهرة دائماً تحت العلامة, وما يتصادم منها يُخفى كما in Google Maps
  // (MikroTik devices أولاً then Sites), وتظهر عند التكبير or بالمرور on العلامة
  // ------------------------------------------------------------------------
  function label(m, text, cls, dy) {
    var t = m.getTooltip();
    if (t && m._snLabel === text + cls) { return; }
    if (t) { m.unbindTooltip(); }
    m._snLabel = text + cls;
    m.bindTooltip(esc(text), { permanent: true, direction: 'bottom', offset: [0, dy], className: 'mk-label ' + cls, opacity: 1, interactive: false });
  }

  var labelsOn = true;
  var declutterTimer = null;
  function declutterSoon() {
    clearTimeout(declutterTimer);
    declutterTimer = setTimeout(declutter, 60);
  }
  function declutter() {
    holder.classList.toggle('hide-labels', !labelsOn);
    if (!labelsOn) { return; }
    var box = holder.getBoundingClientRect();
    var taken = Array.prototype.map.call(holder.querySelectorAll('.leaflet-control'), function (c) { return c.getBoundingClientRect(); });
    var overlaps = function (a, b) { return a.left < b.right + 2 && a.right > b.left - 2 && a.top < b.bottom + 2 && a.bottom > b.top - 2; };
    ['routers', 'sites'].forEach(function (kind) {
      if (!map.hasLayer(groups[kind])) { return; }
      Object.keys(markers[kind]).forEach(function (id) {
        var t = markers[kind][id].getTooltip(), el = t && t.getElement();
        if (!el) { return; }
        el.classList.remove('is-clash');
        var r = el.getBoundingClientRect();
        var outside = r.left < box.left || r.right > box.right || r.top < box.top || r.bottom > box.bottom;
        if (outside || taken.some(function (o) { return overlaps(r, o); })) { el.classList.add('is-clash'); return; }
        taken.push(r);
      });
    });
  }
  map.on('zoomend moveend', declutterSoon);
  var labelsBox = document.querySelector('[data-map-labels]');
  if (labelsBox) {
    try { if (localStorage.getItem('sn-map-labels') === '0') { labelsBox.checked = false; } } catch (e) { /* Storage Unavailable */ }
    labelsOn = labelsBox.checked;
    labelsBox.addEventListener('change', function () {
      labelsOn = labelsBox.checked;
      try { localStorage.setItem('sn-map-labels', labelsOn ? '1' : '0'); } catch (e) { /* Storage Unavailable */ }
      declutter();
    });
  }

  function linkPopup(l) {
    var html = '<div class="pop"><div class="pop-title">' + esc(l.a.name) + ' ⟷ ' + esc(l.b.name) + '</div>' +
      '<div class="pop-sub">' + esc(cfg.linkTypes[l.type] || l.type) + (l.capacity ? ' · <span dir="ltr">' + esc(l.capacity) + '</span>' : '') + '</div>' +
      (l.label ? '<div class="pop-sub">' + esc(l.label) + '</div>' : '');
    if (cfg.canManage) {
      html += '<div class="pop-actions"><button type="button" class="btn btn-xs text-danger" data-pop="del-link" data-id="' + l.id + '">' + SN.icon('trash-2') + 'Delete link</button></div>';
    }
    return html + '</div>';
  }

  function load() {
    return SN.api(cfg.dataUrl, { silent: true }).then(function (d) {
      data = d;
      render();
      var un = d.unplaced || {};
      var box = document.querySelector('[data-unplaced]');
      if (box) {
        var parts = [];
        if (un.sites) { parts.push(SN.fmtNum(un.sites) + ' Site'); }
        if (un.routers) { parts.push(SN.fmtNum(un.routers) + ' MikroTik device'); }
        box.hidden = !parts.length;
        box.querySelector('[data-unplaced-text]').textContent = 'Without coordinates: ' + parts.join(' · ');
      }
      if (firstLoad) {
        firstLoad = false;
        if (!focusTarget() && !cfg.savedView) { fitAll(); }
      }
    }).catch(function () {});
  }

  function reveal(kind, id) {
    var m = markers[kind] && markers[kind][id];
    if (!m) { return false; }
    if (!map.hasLayer(groups[kind])) { map.addLayer(groups[kind]); }
    map.setView(m.getLatLng(), Math.max(map.getZoom(), 17));
    m.openPopup();
    return true;
  }

  /** ?focus=site:5 | router:3 | sub:12 */
  function focusTarget() {
    var f = /[?&]focus=(site|router|sub):(\d+)/.exec(window.location.search);
    if (!f) { return false; }
    return reveal({ site: 'sites', router: 'routers', sub: 'subscribers' }[f[1]], parseInt(f[2], 10));
  }

  function fitAll() {
    var pts = [];
    data.sites.forEach(function (s) { pts.push([s.lat, s.lng]); });
    data.routers.forEach(function (r) { pts.push([r.lat, r.lng]); });
    data.subscribers.forEach(function (s) { pts.push([s.lat, s.lng]); });
    if (pts.length > 1) { map.fitBounds(pts, { padding: [40, 40], maxZoom: 16 }); }
    else if (pts.length === 1) { map.setView(pts[0], 15); }
  }

  // ------------------------------------------------------------------------
  // Layers والبحث
  // ------------------------------------------------------------------------
  document.querySelectorAll('[data-layer]').forEach(function (cb) {
    var key = 'sn-map-layer-' + cb.getAttribute('data-layer');
    try { if (localStorage.getItem(key) === '0') { cb.checked = false; } } catch (e) { /* Storage Unavailable */ }
    var apply = function () {
      var g = groups[cb.getAttribute('data-layer')];
      if (cb.checked) { map.addLayer(g); } else { map.removeLayer(g); }
      try { localStorage.setItem(key, cb.checked ? '1' : '0'); } catch (e) { /* Storage Unavailable */ }
      if (typeof declutterSoon === 'function') { declutterSoon(); }
    };
    cb.addEventListener('change', apply);
    apply();
  });

  var search = document.querySelector('[data-map-search]');
  if (search) {
    search.addEventListener('keydown', function (e) {
      if (e.key !== 'Enter') { return; }
      e.preventDefault();
      var q = search.value.trim().toLowerCase();
      if (!q) { return; }
      var kinds = ['sites', 'routers', 'subscribers'];
      for (var i = 0; i < kinds.length; i++) {
        var list = data[kinds[i]];
        for (var j = 0; j < list.length; j++) {
          if (String(list[j].name).toLowerCase().indexOf(q) !== -1) {
            reveal(kinds[i], list[j].id);
            return;
          }
        }
      }
      SN.toast('info', 'No matching result.');
    });
  }

  // ------------------------------------------------------------------------
  // Administration: Add Site, Links, التحريك
  // ------------------------------------------------------------------------
  function setMode(m) {
    mode = mode === m ? '' : m;
    holder.setAttribute('data-mode', mode);
    document.querySelectorAll('[data-map-act]').forEach(function (b) {
      var on = b.getAttribute('data-map-act') === mode;
      b.classList.toggle('btn-primary', on || (b.getAttribute('data-map-act') === 'add' && mode === ''));
      b.setAttribute('aria-pressed', on ? 'true' : 'false');
    });
    ['sites', 'routers', 'subscribers'].forEach(function (k) {
      Object.keys(markers[k]).forEach(function (id) {
        var mk = markers[k][id];
        if (mk.dragging) { if (mode === 'move') { mk.dragging.enable(); } else { mk.dragging.disable(); } }
      });
    });
    if (mode !== 'link') { markLinkFrom(null); }
    var hint = {
      add: 'Tap the map where the new site is.', router: 'Tap the map where the device is.',
      link: 'Tap the first site, then the second.', move: 'Drag the markers into place; each position is saved right away.'
    }[mode];
    if (hint) { SN.toast('info', hint); }
  }

  /** تمييز First site عند رسم Link */
  function markLinkFrom(id) {
    if (linkFrom && markers.sites[linkFrom] && markers.sites[linkFrom].getElement()) {
      markers.sites[linkFrom].getElement().classList.remove('is-picked');
    }
    linkFrom = id;
    if (id && markers.sites[id] && markers.sites[id].getElement()) {
      markers.sites[id].getElement().classList.add('is-picked');
    }
  }

  var siteForm = document.querySelector('[data-site-form]');
  var linkForm = document.querySelector('[data-link-form]');

  function openSite(site, latlng) {
    if (!siteForm) { return; }
    siteForm.reset();
    siteForm.id.value = site ? site.id : '';
    document.querySelector('[data-site-title]').textContent = site ? site.name : 'New site';
    if (site) {
      siteForm.name.value = site.name;
      siteForm.type.value = site.type;
      siteForm.area_id.value = site.area_id || '';
      siteForm.height_m.value = site.height || '';
      siteForm.address.value = site.address || '';
      siteForm.notes.value = site.notes || '';
      siteForm.lat.value = site.lat;
      siteForm.lng.value = site.lng;
    } else if (latlng) {
      siteForm.lat.value = Math.round(latlng.lat * 1e7) / 1e7;
      siteForm.lng.value = Math.round(latlng.lng * 1e7) / 1e7;
    }
    document.querySelector('[data-site-delete]').hidden = !site;
    SN.openModal('site-modal');
  }

  function openLink(a, b) {
    if (!linkForm) { return; }
    linkForm.reset();
    if (a) { linkForm.site_a.value = a; }
    if (b) { linkForm.site_b.value = b; }
    SN.openModal('link-modal');
  }

  function pickLinkEnd(s) {
    if (!linkFrom) {
      markLinkFrom(s.id);
      map.closePopup();
      return;
    }
    if (linkFrom === s.id) { return; }
    var a = linkFrom;
    setMode('link');
    map.closePopup();
    openLink(a, s.id);
  }

  map.on('click', function (e) {
    if (mode === 'add') { setMode('add'); openSite(null, e.latlng); }
    else if (mode === 'router') { setMode('router'); openRouter(null, e.latlng); }
  });

  // ------------------------------------------------------------------------
  // Add a MikroTik device to the map: اختيار Device and Edit اسمه, or Add device New for the system بهذا Location
  // ------------------------------------------------------------------------
  var routerForm = document.querySelector('[data-router-form]');
  function routerName(id) {
    var r = (cfg.routers || []).filter(function (x) { return x.id === id; })[0];
    return r ? r.name : '';
  }
  function openRouter(id, latlng) {
    if (!routerForm) { return; }
    routerForm.reset();
    var lat = Math.round(latlng.lat * 1e7) / 1e7, lng = Math.round(latlng.lng * 1e7) / 1e7;
    routerForm.lat.value = lat;
    routerForm.lng.value = lng;
    routerForm.querySelector('[data-router-coords]').textContent = lat.toFixed(6) + ', ' + lng.toFixed(6);
    if (routerForm.id) {
      if (!id) {
        var free = (cfg.routers || []).filter(function (x) { return !x.placed; })[0];
        id = free ? free.id : null;
      }
      routerForm.id.value = id ? String(id) : '';
      routerForm.name.value = id ? routerName(id) : '';
    }
    var add = routerForm.querySelector('[data-router-new]');
    if (add) { add.href = url('/routers/create') + '?lat=' + lat + '&lng=' + lng; }
    SN.openModal('router-modal');
  }
  if (routerForm) {
    if (routerForm.id) {
      routerForm.id.addEventListener('change', function () { routerForm.name.value = routerName(parseInt(routerForm.id.value, 10)); });
    }
    routerForm.addEventListener('submit', function (e) {
      e.preventDefault();
      SN.api(cfg.routerUrl, { method: 'POST', form: routerForm }).then(function (r) {
        SN.toast('success', r.message);
        SN.closeModal(document.getElementById('router-modal'));
        (cfg.routers || []).forEach(function (x) { if (x.id === r.id) { x.placed = true; x.name = r.name; } });
        var opt = routerForm.id.querySelector('option[value="' + r.id + '"]');
        if (opt) { opt.textContent = r.name + ' · on the map'; }
        load().then(function () { reveal('routers', r.id); });
      });
    });
  }

  document.addEventListener('click', function (e) {
    var act = e.target.closest('[data-map-act]');
    if (act) {
      var a = act.getAttribute('data-map-act');
      if (a === 'save-view') {
        var c = map.getCenter();
        SN.api(cfg.viewUrl, { method: 'POST', data: { lat: c.lat, lng: c.lng, zoom: map.getZoom() } }).then(function (r) { SN.toast('success', r.message); });
      } else {
        setMode(a);
      }
      return;
    }
    var pop = e.target.closest('[data-pop]');
    if (!pop) { return; }
    var id = parseInt(pop.getAttribute('data-id'), 10);
    var kind = pop.getAttribute('data-pop');
    if (kind === 'edit-site') {
      map.closePopup();
      openSite(data.sites.filter(function (s) { return s.id === id; })[0] || null);
    } else if (kind === 'link-from') {
      if (mode !== 'link') { setMode('link'); }
      markLinkFrom(id);
      map.closePopup();
    } else if (kind === 'edit-router') {
      var rr = data.routers.filter(function (x) { return x.id === id; })[0];
      map.closePopup();
      if (rr) { openRouter(id, L.latLng(rr.lat, rr.lng)); }
    } else if (kind === 'unplace-router') {
      SN.confirm('Remove the device from the map? It stays in the system, and goes back to its tower’s location if it has one.').then(function (ok) {
        if (!ok) { return; }
        SN.api(url('/map/router/' + id + '/remove'), { method: 'POST', data: {} }).then(function (r) {
          SN.toast('success', r.message);
          map.closePopup();
          load();
        });
      });
    } else if (kind === 'del-link') {
      SN.confirm('Delete this link?').then(function (ok) {
        if (!ok) { return; }
        SN.api(url('/sites/links/' + id + '/delete'), { method: 'POST', data: {} }).then(function (r) { SN.toast('success', r.message); map.closePopup(); load(); });
      });
    }
  });

  if (siteForm) {
    siteForm.addEventListener('submit', function (e) {
      e.preventDefault();
      var id = siteForm.id.value;
      SN.api(id ? cfg.sitesUrl + '/' + id : cfg.sitesUrl, { method: 'POST', form: siteForm }).then(function (r) {
        SN.toast('success', r.message);
        SN.closeModal(document.getElementById('site-modal'));
        load();
      });
    });
    document.querySelector('[data-site-delete]').addEventListener('click', function () {
      var id = siteForm.id.value;
      SN.confirm('Delete site “' + siteForm.name.value + '”? Its links will be deleted too.').then(function (ok) {
        if (!ok) { return; }
        SN.api(cfg.sitesUrl + '/' + id + '/delete', { method: 'POST', data: {} }).then(function (r) {
          SN.toast('success', r.message);
          SN.closeModal(document.getElementById('site-modal'));
          load();
        });
      });
    });
  }
  if (linkForm) {
    linkForm.addEventListener('submit', function (e) {
      e.preventDefault();
      SN.api(cfg.linksUrl, { method: 'POST', form: linkForm }).then(function (r) {
        SN.toast('success', r.message);
        SN.closeModal(document.getElementById('link-modal'));
        load();
      });
    });
  }

  load();
  setInterval(function () { if (!document.hidden) { load(); } }, 60000);
  window.addEventListener('resize', function () { map.invalidateSize(); });
})(window, document);
